import{c as l,Q as i,j as t,m as e}from"./chunks/framework.BPKcPtvA.js";const r="/images/class-rGKobabtsBwqzey.jpg",_=JSON.parse('{"title":"商人攻略 - 技能加点/转职/练级","description":"RO3 商人 1-99 级技能加点、转职任务、练级路线、赚钱攻略","frontmatter":{"title":"商人攻略 - 技能加点/转职/练级","description":"RO3 商人 1-99 级技能加点、转职任务、练级路线、赚钱攻略"},"headers":[],"relativePath":"jobs/merchant.md","filePath":"jobs/merchant.md","lastUpdated":1780230058000}'),o={name:"jobs/merchant.md"};function n(s,a,h,d,c,u){return i(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="商人-推荐经济型玩家-副号" tabindex="-1">商人（推荐经济型玩家/副号） <a class="header-anchor" href="#商人-推荐经济型玩家-副号" aria-label="Permalink to &quot;商人（推荐经济型玩家/副号）&quot;">​</a></h1><p><img src="'+r+'" alt="RO3 商人职业立绘"></p><p>商人是 RO3 的经济型职业，后期转职铁匠可以做装备、精炼武器，是目前版本赚钱能力最强的职业之一。</p><h2 id="技能加点" tabindex="-1">技能加点 <a class="header-anchor" href="#技能加点" aria-label="Permalink to &quot;技能加点&quot;">​</a></h2><p><strong>1-10 级</strong>：点满「负重量增加」（核心技能，搬砖必须），「金钱攻击」点 3 级（前期输出）</p><p><strong>11-30 级</strong>：点满「金钱攻击」（用钱砸人，前期唯一输出），「手推车使用」点满（负重翻倍）</p><p><strong>31-60 级</strong>：点满「低价买进」（省钱神技），「高价卖出」点满（卖东西多赚钱）</p><p><strong>61-99 级</strong>：点满「武器制作」（铁匠核心）、「精炼武器」（赚钱核心技能）</p><h2 id="转职任务流程-20级转职" tabindex="-1">转职任务流程（20级转职） <a class="header-anchor" href="#转职任务流程-20级转职" aria-label="Permalink to &quot;转职任务流程（20级转职）&quot;">​</a></h2><ol><li>艾尔贝塔找「商人公会会长」（坐标 60,120），接取任务</li><li>携带 5 万z 证明自己的商业头脑（对话消耗，不会消失）</li><li>从艾尔贝塔跑到普隆德拉和 NPC 交易（跟随指引跑腿）</li><li>回到商人公会，获得商人资格</li></ol><h2 id="各等级段练级点" tabindex="-1">各等级段练级点 <a class="header-anchor" href="#各等级段练级点" aria-label="Permalink to &quot;各等级段练级点&quot;">​</a></h2><ul><li><strong>1-20 级</strong>：南门平原（金钱攻击秒波利）</li><li><strong>21-40 级</strong>：蚂蚁洞（金钱攻击秒蚂蚁，消耗金币但效率高）</li><li><strong>41-60 级</strong>：欧克洞窟（组队，商人负责携带补给）</li><li><strong>61-99 级</strong>：跟着队伍混经验，商人练级速度较慢</li></ul><h2 id="赚钱攻略" tabindex="-1">赚钱攻略 <a class="header-anchor" href="#赚钱攻略" aria-label="Permalink to &quot;赚钱攻略&quot;">​</a></h2><h3 id="_1-摆摊交易" tabindex="-1">1. 摆摊交易 <a class="header-anchor" href="#_1-摆摊交易" aria-label="Permalink to &quot;1. 摆摊交易&quot;">​</a></h3><p>利用「低价买进」「高价卖出」技能低买高卖：</p><ul><li>低价收购热门材料（铝、神之金属）</li><li>高价出售成品装备</li><li>倒卖卡片赚差价</li></ul><h3 id="_2-装备制作" tabindex="-1">2. 装备制作 <a class="header-anchor" href="#_2-装备制作" aria-label="Permalink to &quot;2. 装备制作&quot;">​</a></h3><p>铁匠可以制作高需求装备：</p><ul><li>收集材料制作热门武器</li><li>精炼 +7 以上装备出售</li><li>制作属性武器（火/水/风/地属性）</li></ul><h3 id="_3-搬砖路线" tabindex="-1">3. 搬砖路线 <a class="header-anchor" href="#_3-搬砖路线" aria-label="Permalink to &quot;3. 搬砖路线&quot;">​</a></h3><ul><li>30 级前：刷蚂蚁卵卖材料</li><li>40 级后：刷铝矿（米尔顿斯）</li><li>60 级后：刷神之金属（古城区域）</li><li>挂机卖垃圾 + 制作装备双线赚钱</li></ul><h2 id="练级建议" tabindex="-1">练级建议 <a class="header-anchor" href="#练级建议" aria-label="Permalink to &quot;练级建议&quot;">​</a></h2><p>商人练级效率偏低，建议：</p><ul><li>作为副号使用，主号带练</li><li>或者专注于商业玩法，等级够用就行</li><li>组队时负责携带补给和 buff 道具</li></ul>',24)])])}const m=l(o,[["render",n]]);export{_ as __pageData,m as default};
